package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
)

var files = map[string][]byte{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		file, header, _ := r.FormFile("file")
		defer file.Close()
		data, _ := io.ReadAll(file)
		files[header.Filename] = data
		json.NewEncoder(w).Encode(map[string]interface{}{"name": header.Filename, "size": len(data), "type": header.Header.Get("Content-Type")})
	})

	http.HandleFunc("/upload-form", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		w.Write([]byte(`<form action="/upload" method="POST" enctype="multipart/form-data"><input type="file" name="file"><button type="submit">Upload</button></form>`))
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}

