package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
)

var files = map[string]struct {
	data     []byte
	mimetype string
}{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		file, header, _ := r.FormFile("file")
		defer file.Close()
		data, _ := io.ReadAll(file)
		files[header.Filename] = struct {
			data     []byte
			mimetype string
		}{data, header.Header.Get("Content-Type")}
		json.NewEncoder(w).Encode(map[string]interface{}{"name": header.Filename, "size": len(data), "type": header.Header.Get("Content-Type")})
	})

	http.HandleFunc("/files/", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(r.URL.Path, "/files/")
		f, ok := files[name]
		if !ok { w.WriteHeader(404); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
		w.Header().Set("Content-Type", f.mimetype)
		w.Write(f.data)
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}
